package llmverify
import chisel3._
import chisel3.util._
import chiselFv._

class luckySeven extends Module with Formal {
  val io = IO(new Bundle {
    val from = Input(UInt(3.W))
    val to = Input(UInt(3.W))
    // Add outputs to preserve the design
    val b_out = Output(Vec(8, UInt(3.W)))
    val valid_out = Output(Bool())
    val permutation_out = Output(Bool())
  })

  // Internal registers
  val b = RegInit(VecInit(Seq.tabulate(8)(i => i.U(3.W))))
  val freg = RegInit(0.U(3.W))
  val treg = RegInit(0.U(3.W))

  // Latch inputs on clock edge
  freg := io.from
  treg := io.to

  // Valid move predicate
  val valid = (b(treg) === 0.U) && (
    (treg === (freg + 1.U)) || 
    (freg === (treg + 1.U)) || 
    (treg(1,0) === 0.U && freg(1,0) === 0.U && freg(2) =/= treg(2))
  )

  // Permutation check ensures all board values are unique
  val permutation = b(0) =/= b(1) && b(0) =/= b(2) && b(0) =/= b(3) &&
    b(0) =/= b(4) && b(0) =/= b(5) && b(0) =/= b(6) && b(0) =/= b(7) &&
    b(1) =/= b(2) && b(1) =/= b(3) && b(1) =/= b(4) && b(1) =/= b(5) &&
    b(1) =/= b(6) && b(1) =/= b(7) && b(2) =/= b(3) && b(2) =/= b(4) &&
    b(2) =/= b(5) && b(2) =/= b(6) && b(2) =/= b(7) && b(3) =/= b(4) &&
    b(3) =/= b(5) && b(3) =/= b(6) && b(3) =/= b(7) && b(4) =/= b(5) &&
    b(4) =/= b(6) && b(4) =/= b(7) && b(5) =/= b(6) && b(5) =/= b(7) &&
    b(6) =/= b(7)

  // Perform move if valid
  when(valid) {
    b(treg) := b(freg)
    b(freg) := 0.U
  }

  // Connect outputs
  io.b_out := b
  io.valid_out := valid
  io.permutation_out := permutation

  // ========== Formal Verification Assertions ==========

  // Safety 1: Each board position always holds a value in [0, 7]
  for (i <- 0 until 8) {
    fvAssert(b(i) <= 7.U, s"b($i) should be in range 0-7")
  }

  // Safety 2: The sum of all board values is always 28 (0+1+2+3+4+5+6+7)
  // Use 6-bit sum to avoid overflow (max sum = 56)
  val boardSum = b.map(_.zext()).reduce(_ + _)
  fvAssert(boardSum === 28.S, "board multiset sum invariant: total is always 28")

  // Safety 3: Exactly one empty position (value 0) on the board at all times
  val zeroCount = b.map(v => Mux(v === 0.U, 1.U, 0.U)).reduce(_ + _)
  fvAssert(zeroCount === 1.U, "exactly one empty position (value 0) on the board")

  // Safety 4: When a valid move executes, the board remains a permutation of 0..7
  // (the permutation signal captures uniqueness of all 8 values)
  // If a move is performed, uniqueness must be preserved
  fvAssert(!valid || permutation, "valid moves preserve the permutation invariant")

  // Safety 5: After a valid move, the target position gets the source value
  // and the source position becomes empty (implied by the when block, but assert it)
  val prev_b_freg = RegInit(0.U(3.W))
  val prev_b_treg = RegInit(0.U(3.W))
  when(valid) {
    prev_b_freg := b(freg)
    prev_b_treg := b(treg)
  }
  // On the cycle after a valid move fires:
  // The target (treg) should now hold the old source value (prev_b_freg)
  // The source (freg) should now be 0
  // We use assertNextStepWhen for this
  assertNextStepWhen(valid, b(treg) === prev_b_freg, "after valid move, target gets source value")
  assertNextStepWhen(valid, b(freg) === 0.U, "after valid move, source becomes empty")

  // Safety 6: If from == to, the move cannot be valid (no self-loop)
  fvAssert(!(valid && (freg === treg)), "cannot move from a position to itself")

  // Liveness: If there is an adjacent empty position to any occupied position,
  // a valid move is eventually possible (relaxed liveness)
  // Check that any occupied position (value != 0) that has an empty neighbor
  // will eventually have a valid move opportunity

  // First compute: does there exist some occupied position with an empty neighbor?
  val hasEmptyNeighbor = (0 until 8).map { i =>
    val isOccupied = b(i) =/= 0.U
    val rightEmpty = if (i % 4 < 3) { b(i + 1) === 0.U } else { false.B }
    val leftEmpty = if (i % 4 > 0) { b(i - 1) === 0.U } else { false.B }
    val downEmpty = if (i < 4) { b(i + 4) === 0.U } else { false.B }
    val upEmpty = if (i >= 4) { b(i - 4) === 0.U } else { false.B }
    isOccupied && (rightEmpty || leftEmpty || downEmpty || upEmpty)
  }.reduce(_ || _)

  // The board can always make progress (a valid move exists) unless the board is "solved"
  // (no occupied position has an empty neighbor, which shouldn't happen since exactly one zero exists)
  astRelaxedLiveness(hasEmptyNeighbor, hasEmptyNeighbor || valid, 64, "if an empty-adjacent occupied position exists, a valid move occurs within 64 cycles")
}

